/// One .dkm file of the store as dkrt_scan found it: where it is, what its header says and the needs inferred from its contents (dkneeds). The need_* fields are valid when SCAN_NEEDS is set.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct DkrtScan {
    /// store path, NUL-terminated, for example modules/dyn-demo.dkm
    pub path: [u8; 64],
    /// first sector (relative to the store)
    pub first: u32,
    /// bytes
    pub size: u32,
    /// SCAN_*
    pub flags: u32,
    /// the file's size: it must fit the staging buffer
    pub need_file_size: u32,
    /// the arena block of image and bss
    pub need_arena: u32,
    /// the arena block of the relocated DSP image, held while it is sent (0: no DSP section)
    pub need_arena_xfer: u32,
    /// DSP area bytes: image, bss and voice states (0: no DSP section)
    pub need_dsp_area: u32,
    pub need_dsp_align: u32,
    pub need_machine_rows: u32,
    pub need_voice_rows: u32,
    pub need_param_rows: u32,
    pub need_page_rows: u32,
    pub need_fx_slots: u32,
}
const _: () = assert!(size_of::<DkrtScan>() == 116, "DkrtScan size");
const _: () = assert!(offset_of!(DkrtScan, path) == 0, "DkrtScan.path");
const _: () = assert!(offset_of!(DkrtScan, first) == 64, "DkrtScan.first");
