const _: () = assert!(offset_of!(DkrtScan, need_dsp_area) == 88, "DkrtScan.need_dsp_area");
const _: () = assert!(offset_of!(DkrtScan, need_dsp_align) == 92, "DkrtScan.need_dsp_align");
