/// The fit verdict of one DkrtScan entry. wont is 1 when the module does not fit next to the ticked ones; then short_* is the first short resource (a CAPK_* kind, what the module needs and what is free) and the texts say it. mem is the memory the module takes (arena and DSP area) as text.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct DkrtFitRow {
    pub wont: u32,
    pub short_kind: u32,
    pub short_need: u32,
    pub short_free: u32,
    /// upper case, for a popup: DSP 400K > 254K FREE
    pub reason: [u8; FIT_REASON],
    /// for a list row: DSP 400K>254K
    pub brief: [u8; FIT_BRIEF],
    /// <1K, 259K, 1.2M; empty without SCAN_NEEDS
    pub mem: [u8; FIT_MEM],
}
const _: () = assert!(size_of::<DkrtFitRow>() == 96, "DkrtFitRow size");
const _: () = assert!(offset_of!(DkrtFitRow, wont) == 0, "DkrtFitRow.wont");
const _: () = assert!(offset_of!(DkrtFitRow, short_kind) == 4, "DkrtFitRow.short_kind");
const _: () = assert!(offset_of!(DkrtFitRow, short_need) == 8, "DkrtFitRow.short_need");
const _: () = assert!(offset_of!(DkrtFitRow, short_free) == 12, "DkrtFitRow.short_free");
const _: () = assert!(offset_of!(DkrtFitRow, reason) == 16, "DkrtFitRow.reason");
const _: () = assert!(offset_of!(DkrtFitRow, brief) == 56, "DkrtFitRow.brief");
const _: () = assert!(offset_of!(DkrtFitRow, mem) == 88, "DkrtFitRow.mem");

/// dkrt_fit result: one row per entry and the load line of the ticked set.
#[repr(C)]
pub struct DkrtFitOut {
    /// rows written
    pub count: u32,
    /// DSP 52% CPU 1%; empty when nothing is ticked
    pub line: [u8; FIT_LINE],
    pub rows: [DkrtFitRow; SCAN_MAX],
}
const _: () = assert!(size_of::<DkrtFitOut>() == 3100, "DkrtFitOut size");
